package com.tekwatt.payment.controller;import com.tekwatt.payment.dto.*;import com.tekwatt.payment.service.PaymentService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/payments")public class PaymentController{private final PaymentService service;public PaymentController(PaymentService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)PaymentResponse create(@Valid@RequestBody CreatePaymentRequest r){return service.create(r);}@GetMapping("/{id}")PaymentResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping List<PaymentResponse>list(@RequestParam UUID tenantId){return service.list(tenantId);}@PatchMapping("/{id}/result")PaymentResponse result(@PathVariable UUID id,@Valid@RequestBody PaymentResultRequest r){return service.result(id,r);}@PostMapping("/{id}/refund")PaymentResponse refund(@PathVariable UUID id){return service.refund(id);}}
